        final List<GeoPoint> secondPartPoints = new ArrayList<>();
        final BitSet secondPartInternal = new BitSet();
        loopEdge = edgeBuffer.getNext(checkEdge);
        i = 0;
        while (true) {
          secondPartPoints.add(loopEdge.startPoint);
