 * @param size is the array size.
 * @return an updated index.
 */
private static int getLegalIndex(int index, int size) {
  while (index < 0) {
    index += size;
  }
  while (index >= size) {
    index -= size;
  }
  return index;
}

/** Class representing a single (unused) edge. */
